insert into public.problems (id, title, statement, input_spec, output_spec, notes, examples, tags, rating, time_limit_ms, visibility) values (1234, 'Grand Tour', 'A courier has to visit n cities. The tour starts and ends in city 1 and visits every other city exactly once. Driving from city i to city j takes d_ij minutes, which may be different from d_ji. What is the shortest total time of such a tour?', 'The first line contains n (2 ≤ n ≤ 12). Each of the next n lines contains n integers d_i1 … d_in (0 ≤ d_ij ≤ 10^6, d_ii = 0).', 'Print the minimum total time.', '', '[{"input":"4\n0 10 15 20\n5 0 9 10\n6 13 0 12\n8 8 9 0\n","output":"35"},{"input":"2\n0 3\n4 0\n","output":"7"}]'::jsonb, array['dp','bitmasks']::text[], 2000, 2000, 'public') on conflict (id) do nothing;
