insert into public.problems (id, title, statement, input_spec, output_spec, notes, examples, tags, rating, time_limit_ms, visibility) values (1235, 'Free Tickets', 'There are n towns and m two-way roads. Road i connects towns u_i and v_i and takes w_i minutes to drive. You also have k free tickets: using a ticket on a road makes that drive take 0 minutes. Each ticket can be used only once. What is the shortest travel time from town 1 to town n? Print -1 if town n cannot be reached.', 'The first line contains n, m and k (2 ≤ n ≤ 5000, 0 ≤ m ≤ 10^4, 0 ≤ k ≤ 10). Each of the next m lines contains u_i, v_i and w_i (1 ≤ u_i, v_i ≤ n, u_i ≠ v_i, 1 ≤ w_i ≤ 10^6).', 'Print the shortest time, or -1.', 'In the first example use the ticket on the road from 3 to 4: 2 + 0 = 2 minutes.', '[{"input":"4 4 1\n1 2 5\n2 4 5\n1 3 2\n3 4 9\n","output":"2"},{"input":"3 2 0\n1 2 4\n2 3 4\n","output":"8"}]'::jsonb, array['graphs','shortest paths']::text[], 2100, 2000, 'public') on conflict (id) do nothing;
